//! Idiomatic Rust 2021 translation of the Vulkan 1.4 core API and associated
//! headers.
//!
//! This module consolidates the contents of:
//!   * `vulkan_core.h`
//!   * `vulkan_android.h`, `vulkan_ios.h`, `vulkan_macos.h`, `vulkan_metal.h`,
//!     `vulkan_wayland.h`, `vulkan_win32.h`, `vulkan_xcb.h`, `vulkan_xlib.h`,
//!     `vulkan_fuchsia.h`, `vulkan_screen.h`
//!   * `vulkan_video_codecs.h`, `vulkan_video_codec_h264std.h`,
//!     `vulkan_video_codec_h265std.h`
//!   * `vk_layer.h`, `vk_layer_dispatch_table.h`
//!
//! All opaque handles become `pub type VkXxx = u64` per the project
//! convention.  Public structs use `#[repr(C)]` so the layout matches the
//! reference C ABI.  Only the standard library is required.

#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(non_upper_case_globals)]
#![allow(clippy::all)]

use core::ffi::{self, c_void};

// ===========================================================================
// 1a. Platform-specific opaque types referenced by surface create structs.
// These are forward stubs so the module can compile without linking against
// X11 / Wayland / Android / Metal / Fuchsia / QNX system headers.
// ===========================================================================

// Xlib / X11 (vulkan_xlib.h, vulkan_xcb.h)
pub type Display = c_void;
pub type Window = u64;
pub type xcb_connection_t = c_void;
pub type xcb_window_t = u32;

// Wayland (vulkan_wayland.h)
pub type wl_display = c_void;
pub type wl_surface = c_void;

// Android (vulkan_android.h)
pub type ANativeWindow = c_void;

// Apple Metal (vulkan_metal.h)
pub type CAMetalLayer = c_void;

// Fuchsia (vulkan_fuchsia.h)
pub type zx_handle_t = u32;

// QNX (vulkan_screen.h)
pub type screen_context_t = c_void;
pub type screen_window_t = u32;

// ===========================================================================
// 1. Fundamental scalar / handle types.
// ===========================================================================

/// Vulkan boolean (32-bit, must be `VK_TRUE` or `VK_FALSE`).
pub type VkBool32 = u32;

/// Vulkan opaque device address.
pub type VkDeviceAddress = u64;

/// Vulkan device-memory size / offset.
pub type VkDeviceSize = u64;

/// Generic flag-bits carrier (single 32-bit flagset).
pub type VkFlags = u32;

/// Multisample sample-mask bitset (up to 64 bits).
pub type VkSampleMask = u32;

/// 64-bit flag-bits carrier (used by video extensions).
pub type VkFlags64 = u64;

/// 32-bit bitmask for `Vk*Flags` 64-bit flag-bits types.
pub type VkFlagBits = u32;

